def brave_web_search(workspace_id, api_key_id, query, count=None, offset=None, country=None, search_lang=None, ui_lang=None, safesearch=None, freshness=None, spellcheck=None, result_filter=None, store_raw_response=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0193000" if __import__("os").path.isdir("./environment_mix/0193000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # ---- helpers ----
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # allow trailing Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _period_month(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _make_id(prefix):
        # 18+ base32 chars
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        body = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{body}"

    def _norm_query(q):
        return " ".join(q.strip().split()).lower()

    def _fingerprint(payload_obj):
        b = json.dumps(payload_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _audit(status, workspace_id=None, api_key_id=None, tool=None, search_request_id=None, detail=None):
        # usage_ledger is usage-focused; no request-log collection exists.
        # We'll still record non-billable request events for observability when possible without breaking uniqueness constraints.
        # However, schema enforces unique(search_request_id, event_type); so only record after we have/choose a request id.
        return

    def _sum_usage(usage_rows, ws_id, period, event_type):
        return sum(int(r.get("quantity", 0) or 0) for r in usage_rows
                   if r.get("workspace_id") == ws_id
                   and r.get("period_month") == period
                   and r.get("event_type") == event_type
                   and r.get("billable") is True)

    def _upsert_ledger(usage_rows, ws_id, key_id, req_id, event_type, tool_name, quantity, billable=True):
        # Exactly one row per (search_request_id, event_type)
        for r in usage_rows:
            if r.get("search_request_id") == req_id and r.get("event_type") == event_type:
                # idempotent reconciliation
                r["workspace_id"] = ws_id
                r["api_key_id"] = key_id
                r["tool_name"] = tool_name
                r["quantity"] = int(quantity)
                r["billable"] = bool(billable)
                r["period_month"] = _period_month(now)
                r["updated_at"] = now_iso
                return r
        row = {
            "id": _make_id("brv_use"),
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "search_request_id": req_id,
            "event_type": event_type,
            "tool_name": tool_name,
            "quantity": int(quantity),
            "billable": bool(billable),
            "period_month": _period_month(now),
            "created_at": now_iso,
            "updated_at": now_iso
        }
        usage_rows.append(row)
        return row

    def _redact_raw(obj):
        # Ensure PII-safe-ish: keep only minimal keys for debug if dict/list
        if obj is None:
            return None
        try:
            if isinstance(obj, dict):
                keep = {}
                for k in ("type", "query", "count", "offset", "country", "search_lang", "ui_lang", "safesearch", "freshness", "provider_request_id", "status", "error"):
                    if k in obj:
                        keep[k] = obj[k]
                # include summary counts if present
                for k in ("total", "results_count", "local_results_count"):
                    if k in obj:
                        keep[k] = obj[k]
                return keep
            if isinstance(obj, list):
                return {"items": len(obj)}
            return {"value": str(obj)[:500]}
        except Exception:
            return None

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^brv_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(api_key_id, str) or not re.match(r"^brv_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if not isinstance(query, str) or len(query.strip()) < 1:
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")

    if count is None:
        count = 10
    if offset is None:
        offset = 0
    if store_raw_response is None:
        store_raw_response = False
    if spellcheck is None:
        spellcheck = True
    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if result_filter is None:
        result_filter = ["web"]

    if not isinstance(count, int) or count < 1 or count > 20:
        return _err("VALIDATION_ERROR", "count must be an integer between 1 and 20.")
    if not isinstance(offset, int) or offset < 0 or offset > 1000:
        return _err("VALIDATION_ERROR", "offset must be an integer between 0 and 1000.")
    if country is not None:
        if not isinstance(country, str) or len(country) != 2:
            return _err("VALIDATION_ERROR", "country must be a 2-letter code.")
        country = country.upper()
    for nm, v in (("search_lang", search_lang), ("ui_lang", ui_lang)):
        if v is not None:
            if not isinstance(v, str) or len(v) < 2 or len(v) > 5:
                return _err("VALIDATION_ERROR", f"{nm} must be 2-5 characters.")
    if safesearch is not None and safesearch not in ("off", "moderate", "strict"):
        return _err("VALIDATION_ERROR", "Invalid safesearch.")
    if freshness is not None and freshness not in ("all", "day", "week", "month", "year"):
        return _err("VALIDATION_ERROR", "Invalid freshness.")
    if not isinstance(spellcheck, bool):
        return _err("VALIDATION_ERROR", "spellcheck must be boolean.")
    if not isinstance(store_raw_response, bool):
        return _err("VALIDATION_ERROR", "store_raw_response must be boolean.")
    if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0 or cache_ttl_seconds > 86400:
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be 0..86400.")
    if not isinstance(result_filter, list) or len(result_filter) < 1 or any(x != "web" for x in result_filter) or len(set(result_filter)) != len(result_filter):
        return _err("VALIDATION_ERROR", "result_filter must be a non-empty list containing only 'web'.")

    # ---- load datastore ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_ledger = _load("usage_ledger.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    key = next((k for k in api_keys if k.get("id") == api_key_id and k.get("workspace_id") == workspace_id and k.get("provider") == "brave"), None)
    if not key:
        return _err("UNAUTHORIZED", "API key not found for workspace/provider.", workspace_id=workspace_id, api_key_id=api_key_id)

    # create search request row immediately (business rule)
    req_id = _make_id("brv_req")

    # fingerprint for caching/dedupe
    fp_obj = {
        "tool": "brave_web_search",
        "query": _norm_query(query),
        "count": count,
        "offset": offset,
        "country": country,
        "search_lang": search_lang,
        "ui_lang": ui_lang,
        "safesearch": safesearch,
        "freshness": freshness,
        "spellcheck": spellcheck,
        "result_filter": result_filter
    }
    fingerprint = _fingerprint(fp_obj)

    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "tool_name": "brave_web_search",
        "query_text": query,
        "local_intent": False,
        "fallback_to_web": False,
        "request_fingerprint": fingerprint,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "http_status": None,
        "provider_latency_ms": None,
        "result_count": 0,
        "cached_until": None,
        "provider_request_id": None,
        "raw_response": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    # workspace status gate (must create failed row)
    if ws.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_code"] = "WORKSPACE_NOT_ACTIVE"
        req_row["error_message"] = f"Workspace status is {ws.get('status')}."
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("UNAUTHORIZED", "Workspace is not active; request execution not permitted.", search_request_id=req_id, error_code=req_row["error_code"])

    # api key status gate
    if key.get("status") in ("disabled", "revoked"):
        req_row["status"] = "failed"
        req_row["error_code"] = "API_KEY_NOT_ACTIVE"
        req_row["error_message"] = f"API key status is {key.get('status')}."
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("UNAUTHORIZED", "API key is not active.", search_request_id=req_id, error_code=req_row["error_code"])

    # quota enforcement (monthly_request_quota)
    period = _period_month(now)
    used_req = _sum_usage(usage_ledger, workspace_id, period, "request")
    quota = int(ws.get("monthly_request_quota", 0) or 0)
    if used_req >= quota:
        req_row["status"] = "failed"
        req_row["error_code"] = "MONTHLY_REQUEST_QUOTA_EXCEEDED"
        req_row["error_message"] = "Monthly request quota exceeded."
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", search_request_id=req_id, quota=quota, used=used_req)

    # caching: find existing succeeded request with same fingerprint and cached_until > now
    cached_req = None
    if cache_ttl_seconds > 0:
        for r in reversed(search_requests):
            if r.get("workspace_id") == workspace_id and r.get("request_fingerprint") == fingerprint and r.get("status") in ("succeeded", "cached"):
                cu = _parse_dt(r.get("cached_until"))
                if cu and cu > now:
                    cached_req = r
                    break

    if cached_req:
        # attach/copy results by duplicating rows under this new request id (so unique(search_request_id, rank) holds)
        cached_results = [sr for sr in search_results if sr.get("search_request_id") == cached_req.get("id") and sr.get("status") != "deleted"]
        cached_results.sort(key=lambda x: int(x.get("rank", 10**9)))
        # ensure contiguous
        items = []
        for src in cached_results:
            if src.get("result_type") != "web":
                continue
            items.append(src)

        # paginate
        page_items = items[offset: offset + count]
        new_rows = []
        rank = 1
        for src in page_items:
            # ranks must be contiguous in stored rows for this request. Store only returned page, as tool returns up to count/offset.
            new_rows.append({
                "id": _make_id("brv_res"),
                "search_request_id": req_id,
                "workspace_id": workspace_id,
                "result_type": "web",
                "rank": rank,
                "title": src.get("title"),
                "url": src.get("url"),
                "snippet": src.get("snippet"),
                "display_domain": src.get("display_domain"),
                "language": src.get("language"),
                "published_at": src.get("published_at"),
                "provider_item_id": src.get("provider_item_id"),
                "place": None,
                "status": "active",
                "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat()
            })
            rank += 1

        # write results
        search_results.extend(new_rows)
        _save("search_results.json", search_results)

        req_row["status"] = "cached"
        req_row["result_count"] = len(new_rows)
        req_row["cached_until"] = cached_req.get("cached_until")
        if store_raw_response:
            req_row["raw_response"] = _redact_raw(cached_req.get("raw_response"))
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)

        # ledger rows (idempotent)
        _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "request", "brave_web_search", 1, billable=True)
        _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "result_item", "brave_web_search", req_row["result_count"], billable=True)
        _save("usage_ledger.json", usage_ledger)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "search_request": req_row,
            "results": new_rows,
            "meta": {
                "count": count,
                "offset": offset,
                "returned": len(new_rows),
                "cached": True,
                "latency_ms": latency_ms
            }
        }

    # "execute provider request": offline deterministic pseudo-results
    req_row["status"] = "running"
    req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("search_requests.json", search_requests)

    # simulate provider latency
    provider_latency_ms = 40 + (int(hashlib.md5(fingerprint.encode("utf-8")).hexdigest()[:2], 16) % 180)

    # generate deterministic results for the requested page
    base_seed = int(hashlib.sha256(fingerprint.encode("utf-8")).hexdigest()[:16], 16)
    results = []
    for i in range(count):
        global_rank = offset + i + 1
        # deterministic domain
        dom_seed = (base_seed + global_rank * 1315423911) & 0xFFFFFFFFFFFFFFFF
        domain = f"example{(dom_seed % 997):03d}.com"
        url = f"https://{domain}/search/{base_seed % 1000000}/{global_rank}"
        title = f"{query.strip()} — Result {global_rank}"
        snippet = f"Deterministic offline result {global_rank} for query '{_norm_query(query)}'."
        results.append({
            "id": _make_id("brv_res"),
            "search_request_id": req_id,
            "workspace_id": workspace_id,
            "result_type": "web",
            "rank": i + 1,  # contiguous within this request
            "title": title,
            "url": url,
            "snippet": snippet,
            "display_domain": domain,
            "language": search_lang,
            "published_at": None,
            "provider_item_id": f"brv_web_{base_seed % 1000000}_{global_rank}",
            "place": None,
            "status": "active",
            "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })

    # enforce constraints: url not null for web + contiguous ranks already true
    if any(r.get("url") in (None, "") for r in results):
        req_row["status"] = "failed"
        req_row["error_code"] = "NORMALIZATION_ERROR"
        req_row["error_message"] = "Generated web result missing url."
        req_row["http_status"] = 500
        req_row["provider_latency_ms"] = provider_latency_ms
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("CONFLICT", "Result normalization failed.", search_request_id=req_id)

    # persist results + request
    search_results.extend(results)
    _save("search_results.json", search_results)

    req_row["status"] = "succeeded"
    req_row["http_status"] = 200
    req_row["provider_latency_ms"] = provider_latency_ms
    req_row["result_count"] = len(results)
    if cache_ttl_seconds > 0:
        req_row["cached_until"] = (now + datetime.timedelta(seconds=int(cache_ttl_seconds))).isoformat()
    if store_raw_response:
        req_row["raw_response"] = _redact_raw({
            "type": "brave_web_search",
            "query": query,
            "count": count,
            "offset": offset,
            "country": country,
            "search_lang": search_lang,
            "ui_lang": ui_lang,
            "safesearch": safesearch,
            "freshness": freshness,
            "provider_request_id": req_row["provider_request_id"],
            "results_count": len(results),
            "status": 200
        })
    req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("search_requests.json", search_requests)

    # ledger rows (idempotent)
    _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "request", "brave_web_search", 1, billable=True)
    _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "result_item", "brave_web_search", req_row["result_count"], billable=True)
    _save("usage_ledger.json", usage_ledger)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": req_row,
        "results": results,
        "meta": {
            "count": count,
            "offset": offset,
            "returned": len(results),
            "cached": False,
            "latency_ms": latency_ms
        }
    }

