        return _err("VALIDATION_ERROR", "fallback_to_web must be boolean.")
    if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0 or cache_ttl_seconds > 86400:
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be 0..86400.")
    if location is not None:
        if not isinstance(location, dict):
            return _err("VALIDATION_ERROR", "location must be an object.")
        allowed = {"latitude", "longitude", "radius_km"}
        if any(k not in allowed for k in location.keys()):
            return _err("VALIDATION_ERROR", "location has unknown fields.")
        if "latitude" not in location or "longitude" not in location:
            return _err("VALIDATION_ERROR", "location.latitude and location.longitude are required.")
        lat = location.get("latitude")
        lon = location.get("longitude")
        rad = location.get("radius_km", None)
        if not isinstance(lat, (int, float)) or lat < -90 or lat > 90:
            return _err("VALIDATION_ERROR", "location.latitude out of range.")
        if not isinstance(lon, (int, float)) or lon < -180 or lon > 180:
            return _err("VALIDATION_ERROR", "location.longitude out of range.")
        if rad is not None:
            if not isinstance(rad, (int, float)) or rad < 0.1 or rad > 200:
                return _err("VALIDATION_ERROR", "location.radius_km out of range.")

    # ---- load datastore ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_ledger = _load("usage_ledger.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    key = next((k for k in api_keys if k.get("id") == api_key_id and k.get("workspace_id") == workspace_id and k.get("provider") == "brave"), None)
    if not key:
        return _err("UNAUTHORIZED", "API key not found for workspace/provider.", workspace_id=workspace_id, api_key_id=api_key_id)

    req_id = _make_id("brv_req")

    fp_obj = {
        "tool": "brave_local_search",
        "query": _norm_query(query),
        "count": count,
        "offset": offset,
        "country": country,
        "search_lang": search_lang,
        "ui_lang": ui_lang,
        "safesearch": safesearch,
        "location": location,
        "fallback_to_web": fallback_to_web
    }
    fingerprint = _fingerprint(fp_obj)

    # create search request row immediately
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "tool_name": "brave_local_search",
        "query_text": query,
        "local_intent": True,
        "fallback_to_web": False,
        "request_fingerprint": fingerprint,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "http_status": None,
        "provider_latency_ms": None,
        "result_count": 0,
        "cached_until": None,
        "provider_request_id": None,
        "raw_response": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    if ws.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_code"] = "WORKSPACE_NOT_ACTIVE"
        req_row["error_message"] = f"Workspace status is {ws.get('status')}."
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("UNAUTHORIZED", "Workspace is not active; request execution not permitted.", search_request_id=req_id, error_code=req_row["error_code"])

    if key.get("status") in ("disabled", "revoked"):
        req_row["status"] = "failed"
        req_row["error_code"] = "API_KEY_NOT_ACTIVE"
        req_row["error_message"] = f"API key status is {key.get('status')}."
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("UNAUTHORIZED", "API key is not active.", search_request_id=req_id, error_code=req_row["error_code"])

    # quota enforcement
    period = _period_month(now)
    used_req = _sum_usage(usage_ledger, workspace_id, period, "request")
    quota = int(ws.get("monthly_request_quota", 0) or 0)
    if used_req >= quota:
        req_row["status"] = "failed"
        req_row["error_code"] = "MONTHLY_REQUEST_QUOTA_EXCEEDED"
        req_row["error_message"] = "Monthly request quota exceeded."
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", search_request_id=req_id, quota=quota, used=used_req)

    # caching
    cached_req = None
    if cache_ttl_seconds > 0:
        for r in reversed(search_requests):
            if r.get("workspace_id") == workspace_id and r.get("request_fingerprint") == fingerprint and r.get("status") in ("succeeded", "cached"):
                cu = _parse_dt(r.get("cached_until"))
                if cu and cu > now:
                    cached_req = r
                    break

    if cached_req:
        cached_results = [sr for sr in search_results if sr.get("search_request_id") == cached_req.get("id") and sr.get("status") != "deleted"]
        cached_results.sort(key=lambda x: int(x.get("rank", 10**9)))
        items = [x for x in cached_results if x.get("result_type") in ("local_place", "web")]
        page_items = items[offset: offset + count]

        new_rows = []
        rank = 1
        for src in page_items:
            rt = src.get("result_type")
            new_rows.append({
                "id": _make_id("brv_res"),
                "search_request_id": req_id,
                "workspace_id": workspace_id,
                "result_type": rt,
                "rank": rank,
                "title": src.get("title"),
                "url": src.get("url") if rt == "web" else None,
                "snippet": src.get("snippet"),
                "display_domain": src.get("display_domain") if rt == "web" else None,
                "language": src.get("language"),
                "published_at": src.get("published_at"),
                "provider_item_id": src.get("provider_item_id"),
                "place": src.get("place") if rt == "local_place" else None,
                "status": "active",
                "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat()
            })
            rank += 1

        search_results.extend(new_rows)
        _save("search_results.json", search_results)

        req_row["status"] = "cached"
        req_row["result_count"] = len(new_rows)
        req_row["cached_until"] = cached_req.get("cached_until")
        if store_raw_response:
            req_row["raw_response"] = _redact_raw(cached_req.get("raw_response"))
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("search_requests.json", search_requests)

        _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "request", "brave_local_search", 1, billable=True)
        _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "result_item", "brave_local_search", req_row["result_count"], billable=True)
        _save("usage_ledger.json", usage_ledger)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "search_request": req_row,
            "results": new_rows,
            "meta": {
                "count": count,
                "offset": offset,
                "returned": len(new_rows),
                "cached": True,
                "latency_ms": latency_ms
            }
        }

    # execute local; if empty and fallback_to_web true => web fallback under same request row
    req_row["status"] = "running"
    req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("search_requests.json", search_requests)

    base_seed = int(hashlib.sha256(fingerprint.encode("utf-8")).hexdigest()[:16], 16)

    # deterministic "local-ness": queries containing certain tokens produce local results; else empty
    local_tokens = ("near", "nearby", "restaurant", "cafe", "hotel", "plumber", "dentist", "pizza", "bar", "coffee", "gas", "pharmacy")
    qn = _norm_query(query)
    has_local = any(tok in qn for tok in local_tokens) or (location is not None)

    results = []
    raw_parts = {"local": None, "web": None}

    if has_local:
        for i in range(count):
            global_rank = offset + i + 1
            place_seed = (base_seed + global_rank * 2654435761) & 0xFFFFFFFFFFFFFFFF
            name = f"{query.strip()} Place {global_rank}"
            lat = None
            lon = None
            if location is not None:
                lat = float(location["latitude"]) + (((place_seed % 2000) - 1000) / 100000.0)
                lon = float(location["longitude"]) + ((((place_seed // 2000) % 2000) - 1000) / 100000.0)
            place_obj = {
                "address": f"{(place_seed % 9999) + 1} Main St",
                "phone": None,
                "categories": ["local"],
                "rating": round(3.5 + ((place_seed % 30) / 20.0), 1),
                "review_count": int(place_seed % 500),
                "opening_hours": None,
                "geo": {"lat": lat, "lng": lon} if (lat is not None and lon is not None) else None
            }
            results.append({
                "id": _make_id("brv_res"),
                "search_request_id": req_id,
                "workspace_id": workspace_id,
                "result_type": "local_place",
                "rank": i + 1,
                "title": name,
                "url": None,
                "snippet": f"Deterministic offline local place result {global_rank}.",
                "display_domain": None,
                "language": search_lang,
                "published_at": None,
                "provider_item_id": f"brv_loc_{base_seed % 1000000}_{global_rank}",
                "place": place_obj,
                "status": "active",
                "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat()
            })
        raw_parts["local"] = _redact_raw({
            "type": "brave_local_search",
            "query": query,
            "count": count,
            "offset": offset,
            "country": country,
            "search_lang": search_lang,
            "ui_lang": ui_lang,
            "safesearch": safesearch,
            "location": location,
            "local_results_count": len(results),
            "status": 200
        })

    # If no local results and fallback enabled => web fallback
    if (not results) and fallback_to_web:
        req_row["fallback_to_web"] = True
        # generate web results within same request row, but result_type web
        for i in range(count):
            global_rank = offset + i + 1
            dom_seed = (base_seed + global_rank * 1315423911 + 7) & 0xFFFFFFFFFFFFFFFF
            domain = f"example{(dom_seed % 997):03d}.com"
            url = f"https://{domain}/local-fallback/{base_seed % 1000000}/{global_rank}"
            results.append({
                "id": _make_id("brv_res"),
                "search_request_id": req_id,
                "workspace_id": workspace_id,
                "result_type": "web",
                "rank": i + 1,
                "title": f"{query.strip()} — Web fallback {global_rank}",
                "url": url,
                "snippet": f"Web fallback result {global_rank} for local query '{_norm_query(query)}'.",
                "display_domain": domain,
                "language": search_lang,
                "published_at": None,
                "provider_item_id": f"brv_webfb_{base_seed % 1000000}_{global_rank}",
                "place": None,
                "status": "active",
                "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat()
            })
        raw_parts["web"] = _redact_raw({
            "type": "brave_web_search",
            "query": query,
            "count": count,
            "offset": offset,
            "country": country,
            "search_lang": search_lang,
            "ui_lang": ui_lang,
            "safesearch": safesearch,
            "web_results_count": len(results),
            "status": 200,
            "fallback_to_web": True
        })

    # validate result constraints
    for r in results:
        if r["result_type"] == "web" and not r.get("url"):
            req_row["status"] = "failed"
            req_row["error_code"] = "NORMALIZATION_ERROR"
            req_row["error_message"] = "Web result missing url."
            req_row["http_status"] = 500
            req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save("search_requests.json", search_requests)
            return _err("CONFLICT", "Result normalization failed.", search_request_id=req_id)
        if r["result_type"] == "local_place" and r.get("place") is None:
            req_row["status"] = "failed"
            req_row["error_code"] = "NORMALIZATION_ERROR"
            req_row["error_message"] = "Local place result missing place object."
            req_row["http_status"] = 500
            req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save("search_requests.json", search_requests)
            return _err("CONFLICT", "Result normalization failed.", search_request_id=req_id)

    # Persist
    search_results.extend(results)
    _save("search_results.json", search_results)

    provider_latency_ms = 50 + (int(hashlib.md5(fingerprint.encode("utf-8")).hexdigest()[:2], 16) % 220)

    req_row["status"] = "succeeded" if results else "failed"
    req_row["http_status"] = 200 if results else 502
    req_row["provider_latency_ms"] = provider_latency_ms
    req_row["result_count"] = len(results)
    if not results:
        req_row["error_code"] = "NO_RESULTS"
        req_row["error_message"] = "No local results and fallback disabled."
    if cache_ttl_seconds > 0:
        req_row["cached_until"] = (now + datetime.timedelta(seconds=int(cache_ttl_seconds))).isoformat()
    if store_raw_response:
        # may include both parts
        req_row["raw_response"] = _redact_raw({
            "type": "brave_local_search",
            "query": query,
            "count": count,
            "offset": offset,
            "country": country,
            "search_lang": search_lang,
            "ui_lang": ui_lang,
            "safesearch": safesearch,
            "location": location,
            "fallback_to_web": req_row["fallback_to_web"],
            "local": raw_parts["local"],
            "web": raw_parts["web"],
            "results_count": len(results),
            "status": req_row["http_status"]
        })
    req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("search_requests.json", search_requests)

    # usage ledger only after success or cache; for failed, do not bill
    if req_row["status"] in ("succeeded", "cached"):
        _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "request", "brave_local_search", 1, billable=True)
        _upsert_ledger(usage_ledger, workspace_id, api_key_id, req_id, "result_item", "brave_local_search", req_row["result_count"], billable=True)
        _save("usage_ledger.json", usage_ledger)

    latency_ms = int((time.time() - t0) * 1000)
    if req_row["status"] == "failed":
        return _err("CONFLICT", "Local search failed.", search_request_id=req_id, error_code=req_row["error_code"], error_message=req_row["error_message"])
    return {
        "search_request": req_row,
        "results": results,
        "meta": {
            "count": count,
            "offset": offset,
            "returned": len(results),
            "fallback_to_web": bool(req_row["fallback_to_web"]),
            "cached": False,
            "latency_ms": latency_ms
        }
    }

def list_search_requests(workspace_id, api_key_id=None, tool_name=None, status=None, created_from=None, created_to=None, page_size=None, page_cursor=None, include_raw_response=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0193000" if __import__("os").path.isdir("./environment_mix/0193000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^brv_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not re.match(r"^brv_key_[0-9A-Z]{18,}$", api_key_id)):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if tool_name is not None and tool_name not in ("brave_web_search", "brave_local_search"):
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    if status is not None:
        if (not isinstance(status, list)) or len(status) < 1 or len(set(status)) != len(status):
            return _err("VALIDATION_ERROR", "status must be a non-empty array of unique values.")
        allowed = {"queued", "running", "succeeded", "failed", "cancelled", "cached"}
        if any(s not in allowed for s in status):
            return _err("VALIDATION_ERROR", "status contains invalid values.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be 1..200.")
    if page_cursor is not None and (not isinstance(page_cursor, str) or len(page_cursor) < 1):
        return _err("VALIDATION_ERROR", "page_cursor must be a non-empty string.")
    if include_raw_response is None:
        include_raw_response = False
    if not isinstance(include_raw_response, bool):
        return _err("VALIDATION_ERROR", "include_raw_response must be boolean.")

    dt_from = _parse_dt(created_from) if created_from is not None else None
    if created_from is not None and dt_from is None:
        return _err("VALIDATION_ERROR", "created_from must be an ISO-8601 date-time.")
    dt_to = _parse_dt(created_to) if created_to is not None else None
    if created_to is not None and dt_to is None:
        return _err("VALIDATION_ERROR", "created_to must be an ISO-8601 date-time.")
    if dt_from and dt_to and dt_from >= dt_to:
        return _err("VALIDATION_ERROR", "created_from must be before created_to.")

    # ---- load datastore ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    usage_ledger = _load("usage_ledger.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    if include_raw_response and ws.get("plan") == "free":
        return _err("UNAUTHORIZED", "Raw response retention is not available on the free plan.")

    if api_key_id is not None:
        key = next((k for k in api_keys if k.get("id") == api_key_id and k.get("workspace_id") == workspace_id and k.get("provider") == "brave"), None)
        if not key:
            return _err("UNAUTHORIZED", "API key not found for workspace/provider.", workspace_id=workspace_id, api_key_id=api_key_id)

    # cursor decoding: base64 JSON {"created_at": "...", "id": "..."}
    cursor_created = None
    cursor_id = None
    if page_cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(page_cursor.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            cursor_created = _parse_dt(obj.get("created_at"))
            cursor_id = obj.get("id")
            if cursor_created is None or not isinstance(cursor_id, str):
                return _err("VALIDATION_ERROR", "Invalid page_cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_cursor.")

    def _created_dt(row):
        dt = _parse_dt(row.get("created_at"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    # filter
    rows = [r for r in search_requests if r.get("workspace_id") == workspace_id]
    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        st = set(status)
        rows = [r for r in rows if r.get("status") in st]
    if dt_from is not None:
        rows = [r for r in rows if _created_dt(r) >= dt_from]
    if dt_to is not None:
        rows = [r for r in rows if _created_dt(r) < dt_to]

    # sort created_at desc, tie-breaker id desc
    rows.sort(key=lambda r: (_created_dt(r), r.get("id", "")), reverse=True)

    # apply cursor (exclusive)
    if cursor_created is not None and cursor_id is not None:
        def after_cursor(r):
            cd = _created_dt(r)
            rid = r.get("id", "")
            # since desc order: include items strictly "less" than cursor in sort key
            if cd < cursor_created:
                return True
            if cd == cursor_created and rid < cursor_id:
                return True
            return False
        rows = [r for r in rows if after_cursor(r)]

    total = len(rows)
    page = rows[:page_size]
    has_more = total > len(page)

    # strip raw_response if not requested
    out = []
    for r in page:
        rr = dict(r)
        if not include_raw_response:
            rr["raw_response"] = None
        out.append(rr)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        obj = {"created_at": last.get("created_at"), "id": last.get("id")}
        b = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # observability without request-log: record a non-billable request usage event if possible? No search_request_id here.
    # Can't satisfy uniqueness constraints without a request id; so only return.

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": out,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms
        }
    }

def get_search_request(workspace_id, search_request_id, include_raw_response=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0193000" if __import__("os").path.isdir("./environment_mix/0193000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(workspace_id, str) or not re.match(r"^brv_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(search_request_id, str) or not re.match(r"^brv_req_[0-9A-Z]{18,}$", search_request_id):
        return _err("VALIDATION_ERROR", "Invalid search_request_id.")
    if include_raw_response is None:
        include_raw_response = False
    if not isinstance(include_raw_response, bool):
        return _err("VALIDATION_ERROR", "include_raw_response must be boolean.")

    workspaces = _load("workspaces.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    if include_raw_response and ws.get("plan") == "free":
        return _err("UNAUTHORIZED", "Raw response retention is not available on the free plan.")

    req = next((r for r in search_requests if r.get("id") == search_request_id), None)
    if not req:
        return _err("NOT_FOUND", "Search request not found.", search_request_id=search_request_id)
    if req.get("workspace_id") != workspace_id:
        return _err("UNAUTHORIZED", "Search request does not belong to the specified workspace.", search_request_id=search_request_id)

    out_req = dict(req)
    if not include_raw_response:
        out_req["raw_response"] = None

    results = [sr for sr in search_results if sr.get("search_request_id") == search_request_id and sr.get("workspace_id") == workspace_id and sr.get("status") != "deleted"]
    results.sort(key=lambda r: int(r.get("rank", 10**9)))

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": out_req,
        "results": results,
        "meta": {
            "result_count": len(results),
            "latency_ms": latency_ms
        }
    }

def list_search_results(workspace_id, search_request_id, result_type=None, status=None, offset=None, count=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0193000" if __import__("os").path.isdir("./environment_mix/0193000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^brv_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(search_request_id, str) or not re.match(r"^brv_req_[0-9A-Z]{18,}$", search_request_id):
        return _err("VALIDATION_ERROR", "Invalid search_request_id.")
    if result_type is not None:
        if not isinstance(result_type, list) or len(result_type) < 1:
            return _err("VALIDATION_ERROR", "result_type must be a non-empty array when provided.")
        allowed_rt = {"web", "local_place"}
        if any((not isinstance(x, str) or x not in allowed_rt) for x in result_type):
            return _err("VALIDATION_ERROR", "result_type contains invalid value(s).")
        if len(set(result_type)) != len(result_type):
            return _err("VALIDATION_ERROR", "result_type must contain unique items.")
    if status is not None:
        if not isinstance(status, list) or len(status) < 1:
            return _err("VALIDATION_ERROR", "status must be a non-empty array when provided.")
        allowed_st = {"active", "redacted", "deleted"}
        if any((not isinstance(x, str) or x not in allowed_st) for x in status):
            return _err("VALIDATION_ERROR", "status contains invalid value(s).")
        if len(set(status)) != len(status):
            return _err("VALIDATION_ERROR", "status must contain unique items.")
    if offset is None:
        offset = 0
    if count is None:
        count = 20
    if not isinstance(offset, int) or offset < 0 or offset > 5000:
        return _err("VALIDATION_ERROR", "offset must be an integer between 0 and 5000.")
    if not isinstance(count, int) or count < 1 or count > 100:
        return _err("VALIDATION_ERROR", "count must be an integer between 1 and 100.")

    # Load datastore
    workspaces = _load("workspaces.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_ledger = _load("usage_ledger.json")

    # Resolve workspace and readability
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        # log call
        usage_ledger.append({
            "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
            "workspace_id": workspace_id,
            "api_key_id": None,
            "search_request_id": None,
            "event_type": "request",
            "tool_name": "brave_web_search",
            "quantity": 0,
            "billable": False,
            "period_month": now.strftime("%Y-%m"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "note": "list_search_results.not_found_workspace",
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("usage_ledger.json", usage_ledger)
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        usage_ledger.append({
            "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
            "workspace_id": workspace_id,
            "api_key_id": None,
            "search_request_id": search_request_id,
            "event_type": "request",
            "tool_name": "brave_web_search",
            "quantity": 0,
            "billable": False,
            "period_month": now.strftime("%Y-%m"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "note": "list_search_results.workspace_deleted",
            "status": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("usage_ledger.json", usage_ledger)
        return _err("UNAUTHORIZED", "Workspace is not readable in its current status.")

    req = next((r for r in search_requests if r.get("id") == search_request_id and r.get("workspace_id") == workspace_id), None)
    if not req:
        usage_ledger.append({
            "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
            "workspace_id": workspace_id,
            "api_key_id": None,
            "search_request_id": search_request_id,
            "event_type": "request",
            "tool_name": "brave_web_search",
            "quantity": 0,
            "billable": False,
            "period_month": now.strftime("%Y-%m"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "note": "list_search_results.not_found_request",
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("usage_ledger.json", usage_ledger)
        return _err("NOT_FOUND", "Search request not found for this workspace.")

    # Filter results
    rows = [r for r in search_results if r.get("workspace_id") == workspace_id and r.get("search_request_id") == search_request_id]
    if result_type is not None:
        rtset = set(result_type)
        rows = [r for r in rows if r.get("result_type") in rtset]
    if status is not None:
        stset = set(status)
        rows = [r for r in rows if r.get("status") in stset]

    # Sort by rank
    def _rank_key(r):
        rk = r.get("rank")
        return rk if isinstance(rk, int) else 10**18
    rows.sort(key=_rank_key)

    total = len(rows)
    page = rows[offset: offset + count]
    has_more = (offset + count) < total
    next_cursor = (offset + count) if has_more else None

    # log call (as a non-billable request usage/audit event; quantity=0 to avoid quota impact)
    usage_ledger.append({
        "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
        "workspace_id": workspace_id,
        "api_key_id": req.get("api_key_id"),
        "search_request_id": search_request_id,
        "event_type": "request",
        "tool_name": req.get("tool_name"),
        "quantity": 0,
        "billable": False,
        "period_month": now.strftime("%Y-%m"),
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "note": "list_search_results",
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("usage_ledger.json", usage_ledger)

    return {
        "data": page,
        "meta": {
            "workspace_id": workspace_id,
            "search_request_id": search_request_id,
            "offset": offset,
            "count": count,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_auth_context(workspace_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0193000" if __import__("os").path.isdir("./environment_mix/0193000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^brv_ws_[0-9A-Z]{18,}$", workspace_id):
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    usage_ledger = _load("usage_ledger.json")

    # Ambient auth: choose a workspace that can serve the call. If workspace_id is provided, require it exist.
    ws = None
    if workspace_id is not None:
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            # log attempt (non-billable audit)
            usage_ledger.append({
                "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
                "workspace_id": workspace_id,
                "api_key_id": None,
                "search_request_id": None,
                "event_type": "request",
                "tool_name": "brave_web_search",
                "quantity": 0,
                "billable": False,
                "period_month": now.strftime("%Y-%m"),
                "created_at": _iso(now),
                "updated_at": _iso(now),
                "note": "get_auth_context.not_found_workspace",
                "status": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("usage_ledger.json", usage_ledger)
            return _err("NOT_FOUND", "Workspace not found.")
    else:
        # Pick any workspace (prefer active) to represent the caller context
        ws = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)
        if ws is None:
            usage_ledger.append({
                "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
                "workspace_id": "unknown",
                "api_key_id": None,
                "search_request_id": None,
                "event_type": "request",
                "tool_name": "brave_web_search",
                "quantity": 0,
                "billable": False,
                "period_month": now.strftime("%Y-%m"),
                "created_at": _iso(now),
                "updated_at": _iso(now),
                "note": "get_auth_context.no_workspaces",
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("usage_ledger.json", usage_ledger)
            return _err("UNAUTHORIZED", "No authenticated workspace context is available.")

    # Compute current month usage for workspace
    period_month = now.strftime("%Y-%m")
    req_used = 0
    item_used = 0
    for e in usage_ledger:
        if e.get("workspace_id") != ws.get("id"):
            continue
        if e.get("period_month") != period_month:
            continue
        if not e.get("billable", False):
            continue
        qty = e.get("quantity")
        if not isinstance(qty, int) or qty < 0:
            continue
        if e.get("event_type") == "request":
            req_used += qty
        elif e.get("event_type") == "result_item":
            item_used += qty

    req_quota = ws.get("monthly_request_quota")
    item_quota = ws.get("monthly_result_item_quota")
    if not isinstance(req_quota, int):
        req_quota = 0
    if not isinstance(item_quota, int):
        item_quota = 0

    # Workspaces readable: in this offline store, ambient identity can read all non-deleted workspaces
    readable = []
    for w in workspaces:
        if w.get("status") != "deleted":
            readable.append({
                "id": w.get("id"),
                "name": w.get("name"),
                "status": w.get("status"),
                "plan": w.get("plan")
            })

    # Entitlements: key management allowed if workspace exists (and typically requires active for create)
    # Include key summary for the workspace
    ws_keys = [k for k in api_keys if k.get("workspace_id") == ws.get("id")]
    key_summaries = [{
        "id": k.get("id"),
        "provider": k.get("provider"),
        "key_name": k.get("key_name"),
        "last4": k.get("last4"),
        "status": k.get("status"),
        "created_at": k.get("created_at"),
        "updated_at": k.get("updated_at"),
    } for k in ws_keys]

    # Log call (non-billable audit)
    usage_ledger.append({
        "id": "brv_use_" + now.strftime("%Y%m%d%H%M%S") + "000000000000000000"[:18],
        "workspace_id": ws.get("id"),
        "api_key_id": None,
        "search_request_id": None,
        "event_type": "request",
        "tool_name": "brave_web_search",
        "quantity": 0,
        "billable": False,
        "period_month": period_month,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "note": "get_auth_context",
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("usage_ledger.json", usage_ledger)

    return {
        "data": {
            "identity": {
                "auth_type": "ambient",
                "workspace_id": ws.get("id")
            },
            "readable_workspaces": readable,
            "workspace": {
                "id": ws.get("id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
                "plan": ws.get("plan"),
                "monthly_request_quota": req_quota,
                "monthly_result_item_quota": item_quota
            } if workspace_id is not None else None,
            "usage": {
                "period_month": period_month,
                "requests_used": req_used,
                "requests_remaining": max(0, req_quota - req_used),
                "result_items_used": item_used,
                "result_items_remaining": max(0, item_quota - item_used)
            } if workspace_id is not None else None,
            "api_keys": key_summaries if workspace_id is not None else None
        }
    }
